<?php
if(!is_file(__DIR__.'/core.php')){http_response_code(404);exit;}
require __DIR__.'/core.php';require __DIR__.'/layout.php';
$_SERVER['SCRIPT_NAME']=preg_replace('~/account/access\.php$~','/account/index.php',$_SERVER['SCRIPT_NAME']);
$error='';$notice='';$secret=null;$data=['members'=>[],'invitations'=>[]];$staff=[];$b=null;
try{
 start();user();$b=business();if(!$b){header('Location: context.php',true,303);exit;}
 if(($_SESSION['business_context']['role']??'')!=='owner'){http_response_code(403);throw new RuntimeException('Only the business owner can manage access.');}
 $scope=['p_business'=>$b['id'],'p_environment'=>$_SESSION['business_context']['environment']];
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();$action=(string)($_POST['action']??'');
  if($action==='invite'){$secret=api('/rest/v1/rpc/business_invite_create',$scope+['p_recipient'=>(string)($_POST['recipient']??''),'p_role'=>(string)($_POST['role']??''),'p_hours'=>24],'POST',$_SESSION['auth']['access_token']);$notice='Invitation created. Share the code privately with the intended account holder.';}
  elseif($action==='revoke_invite'){api('/rest/v1/rpc/business_invite_revoke',$scope+['p_id'=>(string)($_POST['id']??'')],'POST',$_SESSION['auth']['access_token']);$notice='Invitation revoked.';}
  elseif($action==='revoke_member'){api('/rest/v1/rpc/business_membership_revoke',$scope+['p_user'=>(string)($_POST['id']??'')],'POST',$_SESSION['auth']['access_token']);$notice='Access revoked. A fresh invitation is needed to restore access.';}
  elseif($action==='link_worker'){api('/rest/v1/rpc/business_worker_link',$scope+['p_user'=>(string)($_POST['id']??''),'p_staff'=>(string)($_POST['staff']??'')],'POST',$_SESSION['auth']['access_token']);$notice='Worker profile linked.';}
  else throw new RuntimeException('Choose a valid access action.');
 }
 $data=api('/rest/v1/rpc/business_access_list',$scope,'POST',$_SESSION['auth']['access_token']);
 $staff=api('/rest/v1/business_staff?business_id=eq.'.rawurlencode($b['id']).'&environment=eq.'.rawurlencode($scope['p_environment']).'&select=id,name,active',[],'GET',$_SESSION['auth']['access_token']);
}catch(AccountSessionExpired $e){go('signin');}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Access is unavailable.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Access | FaraiOS</title><link rel="stylesheet" href="account.css"><link rel="stylesheet" href="workspace.css"></head><body><main class="role-workspace"><a href="dashboard.php">Dashboard</a> · <a href="context.php">Switch business</a><h1>Access</h1><p><?=esc($b['name']??'Your business')?> · <?=esc($scope['p_environment']??'')?></p>
<?php if($error):?><p role="alert"><?=esc($error)?></p><?php endif;if($notice):?><p role="status"><?=esc($notice)?></p><?php endif;?>
<?php if($secret):?><section class="panel"><h2>Share once</h2><p>This code expires in 24 hours and works only for the intended signed-in account. It is not shown again.</p><label for="invite-code">Invitation code</label><input id="invite-code" readonly value="<?=esc($secret['token'])?>"><label for="invite-business">Business ID</label><input id="invite-business" readonly value="<?=esc($b['id'])?>"><p>Recipient opens <a href="join.php">Join business</a> and enters these details. No email was sent.</p></section><?php endif;?>
<?php if(!$error):?><section class="panel"><h2>Invite account</h2><p>Ask the person to sign in and copy their account ID from Join business. Names and staff email addresses do not grant access.</p><?php form_start();?><input type="hidden" name="action" value="invite"><label for="recipient">Account ID</label><input id="recipient" name="recipient" required pattern="[0-9a-fA-F-]{36}" autocomplete="off"><label for="role">Role</label><select id="role" name="role"><option value="manager">Manager</option><option value="receptionist">Receptionist</option><option value="worker">Worker</option></select><button class="primary">Create invitation</button></form></section>
<h2>Members</h2><div class="access-grid"><?php foreach($data['members'] as $m):?><article><h3><?=esc(ucfirst($m['role']))?></h3><p>Account <?=esc(substr($m['user_id'],0,8))?> · <?=$m['active']?'Active':'Revoked'?></p><?php if($m['role']==='owner'):?><p>Accountable owner — protected.</p><?php elseif($m['active']):form_start();?><input type="hidden" name="action" value="revoke_member"><input type="hidden" name="id" value="<?=esc($m['user_id'])?>"><label><input type="checkbox" required> Revoke this account’s access</label><button>Revoke access</button></form><?php if($m['role']==='worker'):form_start();?><input type="hidden" name="action" value="link_worker"><input type="hidden" name="id" value="<?=esc($m['user_id'])?>"><label>Worker profile<select name="staff" required><option value="">Choose active staff</option><?php foreach($staff as $s)if($s['active']):?><option value="<?=esc($s['id'])?>"><?=esc($s['name'])?></option><?php endif;?></select></label><button>Link worker profile</button></form><?php endif;endif;?></article><?php endforeach;?></div>
<h2>Invitations</h2><?php foreach($data['invitations'] as $i):?><article><h3><?=esc(ucfirst($i['role']))?> · <?=esc(substr($i['recipient'],0,8))?></h3><p><?=$i['accepted']?'Accepted':($i['revoked']?'Revoked':'Expires '.esc($i['expires_at']))?></p><?php if(!$i['accepted']&&!$i['revoked']&&strtotime($i['expires_at'])>time()):form_start();?><input type="hidden" name="action" value="revoke_invite"><input type="hidden" name="id" value="<?=esc($i['id'])?>"><button>Revoke invitation</button></form><?php endif;?></article><?php endforeach;endif;?></main></body></html>
